def transform(grid):
    divider = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] == 4)
    top = grid[:divider]
    bottom = grid[divider + 1:]
    top_bg = _mode(top)
    bottom_bg = _mode(bottom)
    return [[3 if a != top_bg and b == bottom_bg else 5
             for a, b in zip(tr, br)]
            for tr, br in zip(top, bottom)]


def _mode(rows):
    counts = {}
    for row in rows:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    return max(counts, key=counts.get)
